fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate the output vector with the same length as the input
    let mut result = Vec::with_capacity(s.len());
    
    for &c in s.iter() {
        // If c is an ASCII uppercase letter, convert by adding 32 to its code point.
        // Otherwise, leave it unchanged.
        if c >= 'A' && c <= 'Z' {
            // Safe to cast to u8 here because we've checked it's in the ASCII range
            let lower = (c as u8 + 32) as char;
            result.push(lower);
        } else {
            result.push(c);
        }
    }
    
    result
}

